<?php
namespace App\Http\Controllers;
use App\Models\User; use App\Services\UserService; use Illuminate\Http\Request;
class UserController extends Controller { public function __construct(private readonly UserService $service){} public function list(Request $request){return $this->service->list($request);} public function show($id){return $this->service->show($id);} public function store(Request $request){return $this->service->store($request);} public function update(Request $request,User $user){return $this->service->update($request,$user);} public function destroy($id){return $this->service->destroy($id);} public function search(Request $request){return $this->service->search($request);} public function view(string $userName){return $this->service->view($userName);} public function findForEmployer(Request $request){return $this->service->findForEmployer($request);} public function findForOrder(Request $request){return $this->service->findForOrder($request);} }
